head.script:
scwin.clickBzProcsNo = "";
scwin.clickListBzSeq = "";
scwin.vScrenID = "ULDSTF05002.xml";
scwin.arrPar = new Array();

scwin.onpageload = function () {
    scwin.gform_onload();
};

scwin.onpageunload = function () {

};

scwin.gform_onload = async function () {
    //$c.pre_newlisting.fn_initSearchDate(edt_SDate, edt_EDate); //목록검색시작일과 종료일자의 초기값 설정
    //$c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    //목록검색시작일과 종료일자의 초기값 설정
    let vCurDate = $c.date.getServerDateTime("yyyymmdd");
    let vEdate = $c.date.addDate(vCurDate, 60);
    edt_EDate.setValue(vEdate);
    $c.data.comboCbDataSetPeriod(cmb_PeriodTp);

    edt_SDate.setValue("19000101");
    // scwin.gform_onload();
    await scwin.fn_set_code(); // 상장주선인 코드조회
    await scwin.fn_list_sync(); // 조회

    // if (js_market == "1" || js_market == "2") {
    //     $c.cm.setColumnProp(grd_List, "TR_MKT_NM", "Show", false);
    //     $c.stf.setObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD, js_market);
    //     $c.stf.showObj(panel_mkt_gubun, false);
    // } else {
    //     $c.stf.showObj(panel_mkt_gubun, true);
    // }
};

scwin.fn_GetPar = function (arrPar) {
    // 넘길 인수를 지정하는 펑션
    scwin.arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD); // 코드값을 포함할 컨트롤
    scwin.arrPar[1] = $c.stf.getObjectValue(txb_COM_NM); // 명칭값을 포함할 컨트롤
    scwin.arrPar[2] = $c.stf.getObjectValue(rdo_SECUGRP_ID);
    scwin.arrPar[3] = $c.stf.getObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD);
    scwin.arrPar[4] = SEARCH_TYP_SER;
    return scwin.arrPar;
};

scwin.fn_SetPar = function (arrPar) {
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM.setValue(arrPar[0].COM_NM);
};

scwin.fn_GetParForIsuCd = function (arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISU_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = $c.stf.getObjectValue(rdo_SECUGRP_ID);
    arrPar[3] = $c.stf.getObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD);
    arrPar[4] = "SER";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

scwin.fn_SetParForIsuCd = function (arrPar) {
    txb_ISU_CD.setValue(arrPar[0].ISU_CD); // 종옥코드
    txb_ISU_NM.setValue(arrPar[0].ISU_NM); //종목명
};

//상장주선인 조회
scwin.fn_set_code = async function () {

    const sbmOptions = {
        id: "sbm_listLeadcomAll",
        method: "get",
        action: "/api/listing/common/code/list-leadcom-all",
        target: "dlt_codeSelectBox=body",
        isProcessMsg: false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
        cmb_LeadcomMbrNo.setNodeSet("data:" + "dlt_codeSelectBox", "text", "value");
    }
};

//업무처리번호
scwin.fn_setBzProcsNo = function (obj) {
    scwin.clickBzProcsNo = dlt_List.getCellData(obj, "bzProcsNo");
    //alert("fn_setBzProcsNo():"+clickBzProcsNo);
};

scwin.fn_getBzProcsNo = function () {
    return scwin.clickBzProcsNo;
};

scwin.fn_setListBzSeq = function (obj) {
    scwin.clickListBzSeq = dlt_List.getCellData(obj, "listBzSeq");
    //alert("fn_setBzPzrocsNo():"+clickBzProcsNo);

};

scwin.fn_getBzProcsNo = function () {
    return scwin.clickListBzSeq;
};

// 조회버튼 클릭
scwin.btn_Search_onclick = function () {
    $c.date.compareFromToDate(edt_SDate, edt_EDate);

    scwin.fn_set_code();
    scwin.fn_list_sync();
}

// 조회
scwin.fn_list_sync = async function () {
    // 서브미션태우기전에 입렦랎 세팅
    dma_search.set("spotIsuTrdMktTpCd", rdo_SPOT_ISU_TRD_MKT_TP_CD.getValue());
    dma_search.set("secugrpId", rdo_SECUGRP_ID.getValue());
    dma_search.set("isurCd", txb_ISUR_CD.getValue());
    dma_search.set("isuCd", txb_ISU_CD.getValue());
    dma_search.set("leadcomMbrNo", cmb_LeadcomMbrNo.getValue());
    dma_search.set("listLmCdIdx", cmb_LeadcomMbrNo.getSelectedIndex());
    dma_search.set("listLmCd", cmb_ListLMCd.getValue());
    dma_search.set("dateType", rdo_DateType.getValue());
    dma_search.set("startDate", edt_SDate.getValue());
    dma_search.set("endDate", edt_EDate.getValue());

    // 통신
    const sbmOptions = {
        id: "sbm_commitments",
        action: "/api/listing/lstproc/kind/prelisting-kindstk/select-list", // swagger-api 사용 
        method: "get",
        ref: "dma_search", //입력 데이터(데이터 맵) 생성해서 사용 
        target: "dlt_List=body", // 출력 데이터(데이터 리스트) 새엉해서 사용
        isProcessMsg: false,
        gridview: "grd_List"
    };

    // 호출
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
        spn_page.setValue(grd_List.getTotalRow());
    }
};


scwin.grd_List_OnDblClick = function (row, colid) {
    //if (colid=='COM_NM'){

    //}

};
// 그리드 더블클릭 - 상세
scwin.grd_List_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    scwin.fn_OpenDetail(rowIndex, 'U');
};

// 신규버튼 클릭
scwin.btn_New_onclick = function () {
    if (cmb_NEW_SECUGRP_ID.getValue() == "") {
        $c.win.alert("신규등록할 [유가증권]을 선택하세요.");
        cmb_NEW_SECUGRP_ID.focus();
        return;
    } else {
        scwin.fn_OpenDetail(-999);
    }
};

//상세팝업
scwin.fn_OpenDetail = async function (row, disPlayFlag) {
    let hight = "750";
    let yPoint = "30";
    let secugrpId; //증권그룹id

    if (row >= 0) { //신규버튼 선택시
        scwin.fn_setBzProcsNo(row);
        scwin.fn_setListBzSeq(row);
        secugrpId = dlt_List.getCellData(row, 'secugrpId');
    } else {
        scwin.clickBzProcsNo = ""; // 업무처리 번호 초기화
        scwin.clickListBzSeq = "";
        secugrpId = cmb_NEW_SECUGRP_ID.getValue();//$c.stf.getObjectValue(cmb_NEW_SECUGRP_ID);
    }

    if (secugrpId == 'DR' || secugrpId == 'FS') { // 외국주권 이나 주식예탁주권인 경우 - ㅜ가 그리드 띄우기
        hight = "830";
        yPoint = "0";
    }
    //$c.frame.CreateDialogFrame("KIKD_STK_DLG_PREEXAM", "/kindstk/ULDSTF05101.gfm"
    //, $c.lc.getSecuGrpNm(secugrpId) + "  종류주식 예비심사관리", 100, yPoint, 1030, hight, "window");
    const url = "/ui/lst/kindstk/ULDSTF05101.xml";
    const popTitle = $c.lc.getSecuGrpNm(secugrpId) + "종류주식 예비심사관리";

    const opts = {
        id: "ULDSTF05101",
        popupName: popTitle,
        width: 1400,
        height: 1500,
        frameModal: "top",
        mktTpCd: scwin.mktTpCd,
    };

    await $c.win.openPopup(url, opts);
};

//엑셀 다운로드 버튼
scwin.btn_Excel_onclick = function () {
    scwin.fn_ExcelDown();
};
scwin.fn_ExcelDown = function () {
    if (dlt_List.getTotalRow() > 0) {
        //엑셀 로그 

        //grd_List.advancedExcelDownload({fileName: "예비심사", sheetName: "sheet1"});

        $c.data.downloadGridViewExcel(grd_List);
    } else {
        alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

scwin.dts_List_OnLoadError = function () {
    alert_error(dlt_List);
};
scwin.dts_List_OnLoadCompleted = function (rowcount) {
    FillGridHeaderTotalCnt(rowcount, panel_page);
    CloseWin(rowcount, grd_List);
};

//법인코드명 찾기
scwin.txb_ISUR_CD_onblur = function () {
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
//법인코드 검색팝업호출
scwin.btn_CoCdSearch_onclick = async function () {
    const res = await $c.lc.popFindExamCorp(rdo_SECUGRP_ID.getValue());
    if (res) {
        txb_ISUR_CD.setValue(res.isurCd); //법인코드
        txb_COM_NM.setValue(res.comNm); //법인명
    }

};

// 종목코드명 찾기
scwin.btn_ISU_CD_SEARCH_onclick = function () {
    scwin.fn_PopFindKindStkExamIsu();
};
// 예비심사종목찾기 
scwin.fn_PopFindKindStkExamIsu = async function () {
    const winTitle = "종류주식 예비심사 종목 선택";
    const opts = {
        id: "ULDSTF05107",
        popupName: winTitle,
        width: 800,
        height: 780,
        frameModal: "top",
        type: "pageFramePopup",
    };

    const param = {
        "secugrpId": rdo_SECUGRP_ID.getValue(),
        "mktTpCd": rdo_SPOT_ISU_TRD_MKT_TP_CD.getValue(),
        "searchType": "SER"
    };
    const res = await $c.win.openPopup("/ui/lst/kindstk/ULDSTF05107.xml", opts, param);
    //TODO
    // txb_ISU_CD.setValue();
    // txb_ISU_NM.setValue();

};

//기간선택
scwin.cmb_PeriodTp_OnSelChange = function () {
    let vTp = cmb_PeriodTp.getValue();
    //  $c.stf.setFromToDate(1, ibx_fromDd, ibx_toDd);
    $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
};

//닫기버튼 클릭
scwin.btn_Close_onclick = async function () {
    await $c.win.closePopup();
};

scwin.invstgBillAcptDd_customFormatter = function (data, formattedData, rowIndex, columnIndex) {
    if (data.length != 8) {
        return $c.date.dateFormat(data, "yyyy-MM-dd HH:mm:ss");
    } else {
        return $c.date.dateFormat(data, "yyyy-MM-dd");
    }
};
